By Lemma~\ref{triv0}, we can rewrite Proposition \ref{des1} as follows:
   \begin{eqnarray*}
    H^1_{\mathrm{Iw}}(K,T)^1&=&\left\{x\in \mathbb D^\dagger_K(T)^{\psi=1}:\mathrm{Tr}_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_1)=-\theta\circ\varphi^{2-n}(x_1)\text{ for all even }n\ge N+2\right\};\\
    H^1_{\mathrm{Iw}}(K,T)^2&=&\left\{x\in \mathbb D^\dagger_K(T)^{\psi=1}:\mathrm{Tr}_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_2)=-\theta\circ\varphi^{2-n}(x_2)\text{ for all odd }n\ge N+2\right\}.
   \end{eqnarray*}

We have
   \begin{eqnarray*}
    H^1_{\mathrm{Iw}}(K,T)^1&=&\left\{x\in \mathbb D_K(T)^{\psi=1}:\exp^*_{K_n}\circ h^1_{\mathrm{Iw},n}(x)\in K_{n-1}\cdot v_1\text{ for all odd }n\ge N+1\right\},\\
    H^1_{\mathrm{Iw}}(K,T)^2&=&\left\{x\in \mathbb D_K(T)^{\psi=1}:\exp^*_{K_n}\circ h^1_{\mathrm{Iw},n}(x)\in K_{n-1}\cdot v_1\text{ for all even }n\ge N+1\right\}.
   \end{eqnarray*}

For $i\in\{1,2\}$, the image of $H_{f,N,(i)}^1(K_n,T)$ inside $\hat{E}(\mathcal{O}_{K_n})$ coincides with
    \begin{align*}
    \hat{E}_N^i(\mathcal{O}_{K_n})   :=& \left\{x\in\hat{E}(\mathcal{O}_{K_n}): \mathrm{Tr}_{K_n/K_m}x\in \hat{E}(\mathcal{O}_{K_{m-1}})\text{ for all }m\in S_{N,i'}^n \text{ and }\mathrm{Tr}_{K_n/K_N}x=0\right\}\\
    =&\left\{x\in\hat{E}(\mathcal{O}_{K_n}):P_{N,i}^n\circ\log_{\hat{E}}(x)=0\right\}.
    \end{align*}

But $H^1_f(L_{
u,n},T)=H^1_g(L_{
u,n},T)$ by \cite[(3.11.2)]{blochkato90}), we have 
    \[
     H^1_{\mathrm{Iw}}(L_
u,\hat{T})\otimes_{\mathbb Z_p}\mathbb Q_p=\lim_{\leftarrow} H^1_f(L_{
u,n},T)\otimes_{\mathbb Z_p}\mathbb Q_p.
    \]

    It is clear that the quotients $\mathbb D_K(T)^{\psi=1}\slash\mathbb D_{K}(\hat{T})^{\psi=1}$ and $H^1(L_{
u,n},T)\slash H^1_f(L_{
u,n},T)$ are torsion-free over $\mathbb Z_p$.

Therefore,
   \begin{eqnarray*}
    \mathrm{Tr}_{K_n/K_{n-1}}\circ \theta\circ\varphi^{-n}(x)&=&\mathrm{Tr}_{K_n/K_{n-1}}\left(\sum_{i=0}^{p-1}\zeta_{p^n}^i\theta\circ\varphi^{1-n}(x_i)\right)\\
    &=&p\theta\circ\varphi^{1-n}(x_0).
   \end{eqnarray*}

By definitions, we have $\varphi(\log^+(1+\pi))=\frac{p}{q}\log^-(1+\pi)$ and $\varphi(\log^-(1+\pi))=\log^+(1+\pi)$, and that similar relations hold when replacing $\varphi$ by $\psi$. The relations \eqref{basechange} therefore imply that
   \begin{eqnarray}
    \varphi(x_1)+p\psi(x_1)&=&\left(\varphi(x_1')+\psi(qx_1')\right)\log^+(1+\pi); \\
    \varphi(x_2)+p\psi(x_2)&=&\left(\varphi(x_2')+q\psi(x_2')\right)p/q\log^-(1+\pi). \end{eqnarray}

By Lemma~\ref{3des}, we have
   \begin{equation} H^1_{f,N,(1)}(K_n,T)=\left(\left(\exp^*_{K_n}\right)^{-1}\left(K_N\oplus\bigoplus_{m\in S_{N,i'}^n}K_{m}^{(0)}\cdot v_1\right)\right)^{\bot_{[,]}}
   \end{equation}
where $(\star)^{\bot_{[,]}}$ denotes the exact annihilator of $\star$ under the pairing $[\sim,\sim]$.

Therefore,
\begin{equation} x\in\left(\left(\exp^*_{K_n}\right)^{-1}\left(\star\cdot v_1\right)\right)^{\bot_{[,]}}\quad\text{if and only if}\quad x\in\exp_{K_n}\left((\star)^\bot\otimes\mathbb D_{\mathrm{cris}}(V)\right)
\end{equation}
     where $(\star)^\bot$ denotes the orthogonal complement of $\star$ under the pairing
     \begin{align*}
      K_n\times K_n &\rightarrow \mathbb Q_p\\
      (x,y) &\mapsto \mathrm{Tr}_{K_n/\mathbb Q_p}(xy).
     \end{align*}
